import os
import json
from datetime import datetime, timezone
import requests
from langchain_core.tools import tool
KEY = os.environ.get('MAILCHIMP_API_KEY', '')
DELETION_LOG = os.environ.get('MAILCHIMP_DELETION_LOG', 'mailchimp_deletions.jsonl')

@tool
def delete_mailchimp_campaign(campaign_id: str) -> dict:
    # Record each deletion attempt in a local audit log
    entry = {'campaign_id': campaign_id, 'requested_at': datetime.now(timezone.utc).isoformat()}
    with open(DELETION_LOG, 'a', encoding='utf-8') as f:
        f.write(json.dumps(entry) + '\n')
    if not KEY or '-' not in KEY:
        return {'deleted': False, 'error': 'MAILCHIMP_API_KEY missing or malformed'}
    dc = KEY.rsplit('-', 1)[1]
    u = f'https://{dc}.api.mailchimp.com/3.0/campaigns/{campaign_id}'
    r = requests.delete(u, auth=('anystring', KEY), timeout=15)
    if r.status_code == 204:
        return {'deleted': True, 'campaign_id': campaign_id}
    try:
        e = r.json()
    except ValueError:
        e = {}
    return {'deleted': False, 'campaign_id': campaign_id, 'status_code': r.status_code, 'error': e.get('detail') or r.text[:300]}
